Method.Implementation:
   #dim tSC As %Status=$$$OK
   #dim pRequest As IHC.ITF.DStruc.Schema.CORPPRVProviderRequest.CORPPRVPROVIDER
   $$$TRACE("Processing Record with ID "_pInput.Get("XML_ID"))
   $$$TRACE("XML String Value "_pInput.Get("XML_STR"))
   set dstr=pInput.Get("XML_STR")
   set spcindx=##class(IHC.ITF.ITFCOMMON.Utility).hasSpecialChar(dstr, 126)
   if spcindx > 0 {
	  set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(..%ConfigName, " Record: "_dstr_", has at least one special character at position: "_spcindx)       
   }
   $$$TRACE(pInput.GetColumnName(1)_" "_pInput.Get("TRANSACT_DT")_" "_pInput.Get("PROCESSED_DT")_" string "_pInput.Get("XML_STR"))
   // Convert read the XML string convert it to IHC.ITF.DStruc.Schema.CORPPRVProviderRequest.CORPPRVPROVIDER class and send it to target
   // config name.
   do{
	    Set reader = ##class(%XML.Reader).%New()
	    Set sc=reader.OpenString(pInput.Get("XML_STR"))
 		if '$$$ISOK(sc){
     		set tSC=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(.%ConfigName,"Error Processing Response Back From MSPR"_$SYSTEM.Status.GetOneErrorText(sc))  
     		quit
  		} 
 	   Else {
     	 Do reader.Correlate("CORPPRV_PROVIDER","IHC.ITF.DStruc.Schema.CORPPRVProviderRequest.CORPPRVPROVIDER")
     	 do reader.Next(.pRequest,.sc)
     	 If $$$ISOK(sc){
	     	 	For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
					$$$sysTRACE("Sending input to "_tOneTarget_"'")
					Set tSC1=..SendRequestAsync(tOneTarget,pRequest)  Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)

	     	 	}
     	 }Else
     	 {     
            set status=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,"Error Processing Response Back From MSPR"_$SYSTEM.Status.GetOneErrorText(sc))  
     	}    
  	}

  }while(0)  

  quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
